-- Local replay required before any staging promotion.
-- OTOTR FINANCE PASS-THROUGH EXPENSE POSTING RPC CANDIDATE (TX-09)
create or replace function finance_private.current_expense_posting_worker_is_trusted() returns boolean language sql stable security definer set search_path='' as $$select false$$;
create or replace function finance_private.current_actor_can_post_expense(p_actor_id uuid,p_expense_id uuid) returns boolean language sql stable security definer set search_path='' as $$select false$$;
create or replace function finance_private.resolve_expense_posting_context(p_expense_id uuid,p_posting_date date) returns jsonb language sql stable security definer set search_path='' as $$select null::jsonb$$;
create or replace function finance_private.resolve_expense_share_posting_context(p_expense_id uuid,p_expense_share_id uuid,p_posting_date date) returns jsonb language sql stable security definer set search_path='' as $$select null::jsonb$$;
revoke all on function finance_private.current_expense_posting_worker_is_trusted() from public,anon,authenticated;revoke all on function finance_private.current_actor_can_post_expense(uuid,uuid) from public,anon,authenticated;revoke all on function finance_private.resolve_expense_posting_context(uuid,date) from public,anon,authenticated;revoke all on function finance_private.resolve_expense_share_posting_context(uuid,uuid,date) from public,anon,authenticated;
create or replace function finance_api.authorize_expense_posting(p_expense_id uuid,p_permission text) returns boolean language sql stable security definer set search_path='' as $$select p_permission='finance.expenses.post' and auth.uid() is not null and finance_private.current_actor_can_post_expense(auth.uid(),p_expense_id)$$;
create or replace function finance_api.commit_pass_through_expense_posting(p_actor_id uuid,p_expense_id uuid,p_posting_date date,p_expected_version bigint,p_reason_code text,p_note_hash text,p_idempotency_key text,p_intent_hash text,p_correlation_id uuid)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare v_expense finance.pass_through_expenses%rowtype;v_period finance.finance_periods%rowtype;v_context jsonb;v_share_context jsonb;v_share record;v_journal_id uuid;v_accrual_id uuid;v_line integer:=0;v_sequence integer:=0;v_debit numeric(24,8):=0;v_credit numeric(24,8):=0;v_net numeric(24,8):=0;v_tax numeric(24,8):=0;v_gross numeric(24,8):=0;v_share_count integer:=0;v_share_hash text;v_payload jsonb;v_payload_hash text;v_previous_hash text;v_audit_hash text;v_new_version bigint;
begin
 if not finance_private.current_expense_posting_worker_is_trusted() then raise exception using errcode='42501',message='expense posting worker denied';end if;
 if p_actor_id is null or p_expense_id is null or p_posting_date is null or p_expected_version<1 or (p_reason_code is not null and (pg_catalog.btrim(p_reason_code)='' or pg_catalog.length(p_reason_code)>100)) or (p_note_hash is not null and p_note_hash!~'^[a-fA-F0-9]{64}$') or coalesce(pg_catalog.btrim(p_idempotency_key),'')='' or pg_catalog.length(p_idempotency_key)>200 or p_intent_hash!~'^[a-fA-F0-9]{64}$' or p_correlation_id is null then raise exception using errcode='22023',message='required expense posting fields missing';end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('expense-posting:'||p_expense_id::text,0));select * into v_expense from finance.pass_through_expenses e where e.id=p_expense_id for update;
 if not found then raise exception using errcode='P0002',message='pass-through expense not found';end if;
 if v_expense.posting_idempotency_key is not null then if v_expense.posting_idempotency_key=p_idempotency_key and v_expense.posting_intent_hash=p_intent_hash then return pg_catalog.jsonb_build_object('outcome','REPLAY','expenseId',v_expense.id,'journalEntryId',v_expense.journal_entry_id,'status','POSTED','postingDate',v_expense.posting_date,'shareCount',(select pg_catalog.count(*) from finance.expense_shares s where s.pass_through_expense_id=v_expense.id),'version',v_expense.version,'debitTotal',v_expense.distributable_amount::text,'creditTotal',v_expense.distributable_amount::text,'currencyCode',v_expense.currency_code);end if;return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 if v_expense.status<>'APPROVED' or v_expense.version<>p_expected_version or v_expense.approved_by is null or v_expense.approved_by=v_expense.prepared_by then return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 if coalesce(pg_catalog.btrim(v_expense.evidence_object_key),'')='' or v_expense.evidence_hash!~'^[a-fA-F0-9]{64}$' then raise exception using errcode='23514',message='approved expense evidence required';end if;
 if not exists(select 1 from finance.approval_requests ar where ar.legal_entity_id=v_expense.legal_entity_id and ar.subject_type='PASS_THROUGH_EXPENSE' and ar.subject_id=v_expense.id and ar.status='APPROVED' and ar.prepared_by=v_expense.prepared_by and not exists(select 1 from finance.approval_steps s where s.approval_request_id=ar.id and coalesce(s.decision,'')<>'APPROVE')) then raise exception using errcode='23514',message='complete expense approval required';end if;
 select pg_catalog.count(*),coalesce(pg_catalog.sum(s.net_amount),0),coalesce(pg_catalog.sum(s.tax_amount),0),coalesce(pg_catalog.sum(s.share_amount),0),pg_catalog.encode(extensions.digest(pg_catalog.convert_to(pg_catalog.string_agg(s.id::text||':'||s.snapshot_hash||':'||s.net_amount::text||':'||s.tax_amount::text||':'||s.share_amount::text,'|' order by s.allocation_order,s.id),'UTF8'),'sha256'),'hex') into v_share_count,v_net,v_tax,v_gross,v_share_hash from finance.expense_shares s where s.pass_through_expense_id=v_expense.id;
 if v_share_count<1 or v_net<>v_expense.distributable_net_amount or v_tax<>v_expense.distributable_tax_amount or v_gross<>v_expense.distributable_amount or v_gross<=0 then raise exception using errcode='23514',message='expense shares do not equal approved distributable totals';end if;
 v_context:=finance_private.resolve_expense_posting_context(v_expense.id,p_posting_date);if v_context is null or coalesce(v_context->>'approvedShareSetHash','')<>v_share_hash or coalesce(v_context->>'financePeriodId','')!~'^[0-9a-fA-F-]{36}$' then raise exception using errcode='23514',message='approved expense posting context required';end if;
 select * into v_period from finance.finance_periods fp where fp.id=(v_context->>'financePeriodId')::uuid and fp.legal_entity_id=v_expense.legal_entity_id and fp.mode='LIVE' and fp.status='OPEN' and p_posting_date between fp.period_start and fp.period_end for update;
 if not found then raise exception using errcode='23514',message='open live finance period required';end if;
 v_journal_id:=gen_random_uuid();insert into finance.journal_entries(id,legal_entity_id,finance_period_id,idempotency_key,intent_hash,entry_type,business_date,posting_date,status,posted_at_utc,posted_by,created_by,correlation_id) values(v_journal_id,v_expense.legal_entity_id,v_period.id,'expense:'||v_expense.id::text||':'||p_idempotency_key,p_intent_hash,'ACCRUAL',v_expense.expense_date,p_posting_date,'POSTED',pg_catalog.now(),p_actor_id,p_actor_id,p_correlation_id);
 for v_share in select s.* from finance.expense_shares s where s.pass_through_expense_id=v_expense.id order by s.allocation_order,s.id for update loop
  v_sequence:=v_sequence+1;v_share_context:=finance_private.resolve_expense_share_posting_context(v_expense.id,v_share.id,p_posting_date);
  if v_share_context is null or coalesce(v_share_context->>'feeDefinitionId','')!~'^[0-9a-fA-F-]{36}$' or coalesce(pg_catalog.btrim(v_share_context->>'receivableAccountCode'),'')='' or (v_share.net_amount>0 and coalesce(pg_catalog.btrim(v_share_context->>'netCreditAccountCode'),'')='') or (v_share.tax_amount>0 and coalesce(pg_catalog.btrim(v_share_context->>'taxCreditAccountCode'),'')='') or coalesce(v_share_context->>'dueDate','')!~'^\d{4}-\d{2}-\d{2}$' or coalesce((v_share_context->>'scopeValid')::boolean,false) is not true then raise exception using errcode='23514',message='approved expense share accounting context required';end if;
  v_line:=v_line+1;insert into finance.journal_lines(journal_entry_id,line_no,dealer_account_id,account_code,branch_id,currency_code,debit_amount,credit_amount,dimensions,created_by,correlation_id) values(v_journal_id,v_line,v_share.dealer_account_id,v_share_context->>'receivableAccountCode',v_share.branch_id,v_expense.currency_code,v_share.share_amount,0,pg_catalog.jsonb_build_object('expenseId',v_expense.id,'expenseShareId',v_share.id),p_actor_id,p_correlation_id);v_debit:=v_debit+v_share.share_amount;
  if v_share.net_amount>0 then v_line:=v_line+1;insert into finance.journal_lines(journal_entry_id,line_no,dealer_account_id,account_code,branch_id,currency_code,debit_amount,credit_amount,dimensions,created_by,correlation_id) values(v_journal_id,v_line,v_share.dealer_account_id,v_share_context->>'netCreditAccountCode',v_share.branch_id,v_expense.currency_code,0,v_share.net_amount,pg_catalog.jsonb_build_object('expenseId',v_expense.id,'expenseShareId',v_share.id,'component','NET'),p_actor_id,p_correlation_id);v_credit:=v_credit+v_share.net_amount;end if;
  if v_share.tax_amount>0 then v_line:=v_line+1;insert into finance.journal_lines(journal_entry_id,line_no,dealer_account_id,account_code,branch_id,currency_code,debit_amount,credit_amount,dimensions,created_by,correlation_id) values(v_journal_id,v_line,v_share.dealer_account_id,v_share_context->>'taxCreditAccountCode',v_share.branch_id,v_expense.currency_code,0,v_share.tax_amount,pg_catalog.jsonb_build_object('expenseId',v_expense.id,'expenseShareId',v_share.id,'component','TAX'),p_actor_id,p_correlation_id);v_credit:=v_credit+v_share.tax_amount;end if;
  v_accrual_id:=gen_random_uuid();insert into finance.accruals(id,legal_entity_id,calculation_run_id,pass_through_expense_id,dealer_account_id,branch_id,journal_entry_id,sequence_no,fee_definition_id,currency_code,net_amount,tax_amount,gross_amount,status,created_by,correlation_id) values(v_accrual_id,v_expense.legal_entity_id,null,v_expense.id,v_share.dealer_account_id,v_share.branch_id,v_journal_id,v_sequence,(v_share_context->>'feeDefinitionId')::uuid,v_expense.currency_code,v_share.net_amount,v_share.tax_amount,v_share.share_amount,'POSTED',p_actor_id,p_correlation_id);
  insert into finance.open_items(legal_entity_id,accrual_id,dealer_account_id,branch_id,due_date,currency_code,item_type,original_amount,allocated_amount,open_amount,status,created_by,correlation_id) values(v_expense.legal_entity_id,v_accrual_id,v_share.dealer_account_id,v_share.branch_id,(v_share_context->>'dueDate')::date,v_expense.currency_code,'DEBIT',v_share.share_amount,0,v_share.share_amount,'OPEN',p_actor_id,p_correlation_id);update finance.expense_shares set accrual_id=v_accrual_id,correlation_id=p_correlation_id where id=v_share.id and accrual_id is null;if not found then raise exception using errcode='40001',message='expense share already posted';end if;
 end loop;
 if v_debit<>v_credit or v_debit<>v_expense.distributable_amount then raise exception using errcode='23514',message='expense journal is not balanced';end if;
 v_new_version:=v_expense.version+1;update finance.pass_through_expenses set journal_entry_id=v_journal_id,posting_idempotency_key=p_idempotency_key,posting_intent_hash=p_intent_hash,posting_date=p_posting_date,posted_by=p_actor_id,status='POSTED',version=v_new_version,correlation_id=p_correlation_id where id=v_expense.id and version=p_expected_version and status='APPROVED';if not found then raise exception using errcode='40001',message='expense version conflict';end if;
 v_payload:=pg_catalog.jsonb_build_object('expenseId',v_expense.id,'journalEntryId',v_journal_id,'financePeriodId',v_period.id,'postingDate',p_posting_date,'currencyCode',v_expense.currency_code,'debitTotal',v_debit::text,'creditTotal',v_credit::text,'shareCount',v_share_count,'version',v_new_version,'intentHash',p_intent_hash);v_payload_hash:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(v_payload::text,'UTF8'),'sha256'),'hex');insert into finance.outbox_messages(legal_entity_id,topic,event_type,aggregate_type,aggregate_id,aggregate_version,payload,payload_hash,status,correlation_id) values(v_expense.legal_entity_id,'finance.expense','PASS_THROUGH_EXPENSE_POSTED','pass_through_expense',v_expense.id,v_new_version,v_payload,v_payload_hash,'PENDING',p_correlation_id);
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('audit:'||v_expense.legal_entity_id::text,0));select ae.integrity_hash into v_previous_hash from finance.audit_events ae where ae.legal_entity_id=v_expense.legal_entity_id order by ae.created_at_utc desc,ae.id desc limit 1;v_audit_hash:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(coalesce(v_previous_hash,'GENESIS')||':'||v_expense.id::text||':PASS_THROUGH_EXPENSE_POSTED:'||p_intent_hash||':'||p_correlation_id::text,'UTF8'),'sha256'),'hex');insert into finance.audit_events(legal_entity_id,actor_id,actor_type,action_code,subject_type,subject_id,decision,reason_code,after_hash,previous_integrity_hash,integrity_hash,safe_context,correlation_id) values(v_expense.legal_entity_id,p_actor_id,'USER','PASS_THROUGH_EXPENSE_POSTED','pass_through_expense',v_expense.id,'ALLOW',p_reason_code,v_payload_hash,v_previous_hash,v_audit_hash,pg_catalog.jsonb_build_object('journalEntryId',v_journal_id,'financePeriodId',v_period.id,'shareCount',v_share_count,'debitTotal',v_debit::text,'creditTotal',v_credit::text,'noteHash',p_note_hash),p_correlation_id);
 return pg_catalog.jsonb_build_object('outcome','POSTED','expenseId',v_expense.id,'journalEntryId',v_journal_id,'status','POSTED','postingDate',p_posting_date,'shareCount',v_share_count,'version',v_new_version,'debitTotal',v_debit::text,'creditTotal',v_credit::text,'currencyCode',v_expense.currency_code);
end $$;
revoke all on function finance_api.commit_pass_through_expense_posting(uuid,uuid,date,bigint,text,text,text,text,uuid) from public,anon,authenticated;revoke all on function finance_api.authorize_expense_posting(uuid,text) from public,anon;grant execute on function finance_api.authorize_expense_posting(uuid,text) to authenticated;
